entries[30213] = { ["name"] = "Legion Strike", ["text"] = "60 Energy Melee Range\nInstant\nRequires Weapons\nA strong attack that deals [0.816 * (Spell Power * 0.5) * 1 * (1 + Versatility)] damage to all enemies in front of it, and reduces the effectiveness of any healing the victim receives by 20% for 12 sec.\n\n(Right - Click to toggle)" }
